<!--
  Ported to Vue from nexu-io/open-design apps/web/src/components/Icon.tsx (Apache-2.0).
  Glyph data lives in ./Icon.ts (generated by scripts/lib/convert-icon.mjs from the
  upstream file); this component only renders it, with the same markup and classes.
-->
<script setup lang="ts">
import { computed, h, type FunctionalComponent } from 'vue';
import { ICON_GLYPHS, REMIX_ICON, type IconName, type IconNode } from './Icon';
import { REMIX_ICON_PATHS } from './remix-icon-paths';

defineOptions({ name: 'OdIcon' });

const props = withDefaults(
  defineProps<{
    name: IconName;
    size?: number | string;
    strokeWidth?: number | string;
  }>(),
  { size: 14, strokeWidth: 1.6 },
);

const remixPath = computed(() => {
  const glyph = REMIX_ICON[props.name];
  return glyph ? REMIX_ICON_PATHS[glyph] : undefined;
});

const glyph = computed(() => (remixPath.value ? undefined : ICON_GLYPHS[props.name]));

const glyphAttrs = computed<Record<string, unknown>>(() => {
  const current = glyph.value;
  if (!current) return {};
  const common = current.common
    ? {
        width: props.size,
        height: props.size,
        viewBox: '0 0 24 24',
        fill: 'none',
        stroke: 'currentColor',
        'stroke-width': props.strokeWidth,
        'stroke-linecap': 'round',
        'stroke-linejoin': 'round',
        'aria-hidden': 'true',
        focusable: 'false',
      }
    : {};
  return { ...common, ...current.svg };
});

const glyphClass = computed(() => (glyph.value?.className ? `od-icon ${glyph.value.className}` : 'od-icon'));

function renderNodes(nodes: IconNode[]): ReturnType<typeof h>[] {
  return nodes.map(([tag, attrs, children]) => h(tag, attrs, children ? renderNodes(children) : undefined));
}

const GlyphNodes: FunctionalComponent<{ nodes: IconNode[] }> = (p) => renderNodes(p.nodes);
GlyphNodes.props = ['nodes'];
</script>

<template>
  <svg
    v-if="remixPath"
    :width="size"
    :height="size"
    viewBox="0 0 24 24"
    fill="currentColor"
    aria-hidden="true"
    focusable="false"
    :class="name === 'spinner' ? 'od-icon icon-spin' : 'od-icon'"
  >
    <path :d="remixPath" />
  </svg>
  <svg v-else-if="glyph" v-bind="glyphAttrs" :class="glyphClass">
    <GlyphNodes :nodes="glyph.children" />
  </svg>
</template>
